import onnx, numpy as np
from onnx import numpy_helper
def load(p):
    m=onnx.load(p); return {t.name:numpy_helper.to_array(t).astype(np.float64) for t in m.graph.initializer}
A=load('/nets/net1.onnx');B=load('/nets/net2.onnx')
for k in A: d=A[k]-B[k]; print(k, np.abs(d).max(), np.linalg.norm(d), (np.abs(d)>1e-9).sum(), d.size)
def f(w,X):
    h=X.T
    for i in range(4):
        h=w['W%d'%i]@h + w['B%d'%i][:,None]
        if i<3: h=np.maximum(h,0)
    return h.T
X=np.random.uniform(-1,1,(1000000,4))
d=np.abs(f(A,X)-f(B,X)).max(1)
i=d.argmax(); print(d.max(), X[i])
EOF
